        public static string T(string text) => Japanese && text != null && Translations.TryGetValue(text, out var translated) ? translated : text;
        public static void TranslateMenu(VRCExpressionsMenu root)
        {
            if (!Japanese)
                return;
            var visited = new HashSet<VRCExpressionsMenu>();
            void Walk(VRCExpressionsMenu menu)
            {
                if (!menu || !visited.Add(menu))
                    return;
                foreach (var control in menu.controls)
                {
                    // Material names belong to the user, even if they match a built-in label.
                    if (control.parameter == null || control.parameter.name != "ASFR/Style")
                        control.name = T(control.name);
                    Walk(control.subMenu);
                }

                EditorUtility.SetDirty(menu);
            }

            Walk(root);
        }
    }
